from typing import Optional

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class IdmAdminProviderMethod(BaseClient):
    """
    Методы группы 'Аутентификации домена' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=117)
    @tracer.start_as_current_span("admin_provider.idm_admin_provider_create")
    def idm_admin_provider_create(self, _type: str, domain: str) -> dict:
        """
        Добавить тип аутентификации домену
        Добавление нового типа аутентификации домену из Панели администратора
        :param _type: Тип аутентификации
        :param domain: Название домена
        :return: тело ответа сервера
        """
        return self.post(
            "idm/admin/provider/create",
            headers={"Authorization": f"Bearer {self.token}"},
            data={
                "type": _type,
                "domain": domain,
            },
        )

    @api_version_check(min_version=117)
    @tracer.start_as_current_span("admin_provider.idm_admin_provider_delete")
    def idm_admin_provider_delete(self, _type: str, domain: str) -> dict:
        """
        Удалить тип аутентификации из домена
        Удаление типа аутентификации из Панели администратора
        :param _type: Тип аутентификации
        :param domain: Название домена
        :return: тело ответа сервера
        """
        return self.post(
            "idm/admin/provider/delete",
            headers={"Authorization": f"Bearer {self.token}"},
            data={
                "type": _type,
                "domain": domain,
            },
        )

    @api_version_check(min_version=117)
    @tracer.start_as_current_span("admin_provider.idm_admin_provider_list")
    def idm_admin_provider_list(self, domain: str) -> dict:
        """
        Получить список доступных типов аутентификации для домена
        Получение списка доступных типов аутентификации
        :param domain: Название домена
        :return: тело ответа сервера
        """
        return self.post(
            "idm/admin/provider/list",
            headers={"Authorization": f"Bearer {self.token}"},
            data={
                "domain": domain,
            },
        )

    @api_version_check(min_version=117)
    @tracer.start_as_current_span("admin_provider.idm_admin_provider_account_delete")
    def idm_admin_provider_account_delete(self, user_sn: str, _type: str, domain: Optional[str] = None) -> dict:
        """
        Удалить тип аутентификации из аккаунта
        Удаление привязанного типа аутентификации из аккаунта
        :param user_sn: Идентификатор пользователя
        :param _type: Тип аутентификации
        :param domain: Название домена
        :return: тело ответа сервера
        """
        return self.post(
            "idm/admin/provider/account/delete",
            headers={"Authorization": f"Bearer {self.token}"},
            data={
                "aimsid": self.aimsid,
                "r": self.getReqId(),
                "userSn": user_sn,
                "type": type,
                "domain": domain,
            },
        )

    @api_version_check(min_version=117)
    @tracer.start_as_current_span("admin_provider.idm_admin_provider_account_listProviders")
    def idm_admin_provider_account_listProviders(self, user_sn: str, domain: Optional[str] = None) -> dict:
        """
        Показать список типов аутентификаций у пользователя
        Показать список возможных типов аутентификаций у пользователя
        :param user_sn: Идентификатор пользователя
        :param domain: Название домена
        :return: тело ответа сервера
        """
        return self.post(
            "idm/admin/provider/account/listProviders",
            headers={"Authorization": f"Bearer {self.token}"},
            data={
                "aimsid": self.aimsid,
                "r": self.getReqId(),
                "userSn": user_sn,
                "domain": domain,
            },
        )
